const body = $json.body ?? $json;

const phone =
  body.phone ||
  body.telefono ||
  body.contact_phone ||
  null;

const name =
  body.name ||
  body.nombre ||
  "Usuario";

const message =
  body.message ||
  body.text ||
  body.last_user_message ||
  body.mensaje ||
  "";

const text = String(message).trim().toLowerCase();

let action = "generic_reply";
let reply = "";

if (!text) {
  action = "empty_message";
  reply = `Hola ${name}, no he recibido ningún mensaje. ¿Puedes escribirlo de nuevo?`;
} else if (text.includes("demo")) {
  action = "book_demo";
  reply = `Perfecto ${name}. ¿Qué área te interesa más para la demo: CRM, ventas, inventario, fabricación o servicio técnico?`;
} else if (text.includes("precio") || text.includes("coste") || text.includes("costo")) {
  action = "pricing_question";
  reply = `Para darte una orientación realista, necesito saber cuántos usuarios seríais y qué módulos necesitáis.`;
} else if (text.includes("humano") || text.includes("persona") || text.includes("comercial")) {
  action = "transfer_to_human";
  reply = `Perfecto, voy a derivar tu consulta a un especialista de Azordata.`;
} else if (text.includes("stock") || text.includes("inventario")) {
  action = "inventory_interest";
  reply = `Odoo puede centralizar inventario, compras, almacenes y reposición. ¿Tenéis uno o varios almacenes?`;
} else {
  action = "discovery";
  reply = `Encantado de ayudarte, ${name}. Cuéntame qué proceso quieres mejorar en tu empresa y te orientaré sobre cómo hacerlo con Odoo.`;
}

return [
  {
    json: {
      success: true,
      action,
      phone,
      name,
      original_message: message,
      reply,
      source: "spoki",
      received_at: new Date().toISOString()
    }
  }
];
